import { promises } from "fs";
import { join } from "path";
async function copy(src: string, destination: string): Promise<void> {
    const stat = await promises.stat(src); // Get status of source to copy from.

    if (stat.isDirectory()) { // If source is directory:
        const contained = await promises.readdir(src); // Read contents of directory.
        await Promise.all( // Wait for all promises to resolve.
            contained.map((file) => copy(join(src, file), join(destination, file))) // Copy each file to destination path.
        );
    } else if (stat.isFile()) { // If source is file:
        await promises.mkdir(dirname(destination), { recursive: true }); // Create file's path if not exist.
        await promises.copyFile(src, destination); // Copy file to destination.
    }
}
