def subset(nums, n):
    # Sort the list to handle duplicates and make it easier to find consecutive duplicates
    nums.sort()
    count = 1  # Initialize count with 1 for the first element
    for i in range(1, n):
        # Check for consecutive duplicates
        if nums[i] == nums[i - 1]:
            count += 1
        else:
            count = 1
        # If the count exceeds 1, it means we have a subset with more than one duplicate element
        if count > 1:
            return 2
    return 1
